#!/bin/sh
# Name: Vector
# Icon: data:image/png;base64,

documents=/mnt/us/documents
app_dir="$documents/manga-viewer"
viewer="$app_dir/manga_kindle"
log="$app_dir/viewer.log"

if [ ! -r "$viewer" ]; then
    echo 'Manga Viewer needs manga_kindle in documents/manga-viewer.' >&2
    exit 1
fi

set -- --library "$documents" --settings "$app_dir/settings.conf"
loader="$app_dir/lib/ld-musl-armhf.so.1"
if [ -f "$loader" ]; then
    export LIBHEIF_PLUGIN_PATH="$app_dir/lib/libheif"
    [ -x "$loader" ] || chmod u+x "$loader" || exit 1
    set -- "$loader" --library-path "$app_dir/lib" "$viewer" "$@"
else
    [ -x "$viewer" ] || chmod u+x "$viewer" || exit 1
    set -- "$viewer" "$@"
fi

"$@" >"$log" 2>&1
status=$?
if [ "$status" -ne 0 ]; then
    cat "$log" >&2
fi
exit "$status"
